function birthdayThisYear(value,now=new Date()){if(!value)return null;let parts=value.split('-').map(Number),today=new Date(now.getFullYear(),now.getMonth(),now.getDate()),birthday=new Date(now.getFullYear(),parts[1]-1,parts[2]);return birthday>=today?birthday:null}
function birthdayTimeLeft(date,now=new Date()){let today=new Date(now.getFullYear(),now.getMonth(),now.getDate()),days=Math.max(0,Math.round((date-today)/86400000));if(days<=31)return `${days} day${days===1?'':'s'}`;let months=date.getMonth()-today.getMonth();return `${months} month${months===1?'':'s'}`}
function currentYearCelebrations(){let now=new Date(),today=new Date(now.getFullYear(),now.getMonth(),now.getDate()),celebrations=state.designs.map(design=>({...design,next:design.date?new Date(`${design.date}T00:00:00`):null})).filter(design=>design.next&&!Number.isNaN(design.next.getTime())&&design.next.getFullYear()===today.getFullYear()&&design.next>=today).sort((a,b)=>a.next-b.next),visible=celebrations.slice(0,3);if(!visible.length)return empty('No more scheduled celebrations this year');let items=visible.map(design=>{let title=design.memberId?memberName(design.memberId):(design.title||'Untitled design');return `<div class="list-item"><div class="date-tile"><b>${design.next.toLocaleDateString('en-NG',{month:'short'}).toUpperCase()}</b><strong>${design.next.getDate()}</strong></div><div class="grow"><strong>${esc(title)}</strong><small>${esc(design.category||'Celebration')} · Scheduled design</small></div><span class="pill active">${birthdayTimeLeft(design.next)}</span></div>`}).join('');return items+(celebrations.length>3?`<div class="list-item"><div class="grow"><strong>${celebrations.length-3} more upcoming celebration${celebrations.length-3===1?'':'s'}</strong><small>See every scheduled celebration on the Designs page.</small></div><button class="button small ghost" data-page-jump="designs">View more</button></div>`:'')}
