let designPreviewUrls=[];
function postRenderEnhancements(){
  if(current==='dashboard')removeDashboardQuickActions();
  if(current==='contributions')decorateContributionRows();
  if(current==='schedule')decorateMeetingTemplate();
  if(current==='designs'){decorateDesignShareButtons();loadDesignThumbnails()}
}
function removeDashboardQuickActions(){let addArea=document.querySelector('#view .dashboard-add-wrap'),card=addArea?.closest('.card'),layout=card?.parentElement;if(!card||!layout)return;card.remove();layout.classList.add('dashboard-celebrations-only')}
function decorateContributionRows(){
  document.querySelectorAll('#view [data-edit="contribution"]').forEach(edit=>{
    let cell=edit.closest('tr')?.cells?.[0];
    if(!cell||cell.querySelector('[data-view-contribution]'))return;
    let button=document.createElement('button');
    button.type='button';button.className='contribution-link';button.dataset.viewContribution=edit.dataset.id;
    button.title='View members who contributed';button.innerHTML=cell.innerHTML;cell.replaceChildren(button);
    button.onclick=()=>openContributionDetails(edit.dataset.id);
  });
}
function openContributionDetails(id){
  let contribution=state.contributionTypes.find(item=>item.id===id),dialog=document.getElementById('contributionDialog'),body=document.getElementById('contributionDetailBody');
  if(!contribution||!dialog||!body)return;
  let grouped={};
  state.payments.filter(payment=>payment.typeId===id).forEach(payment=>{let key=payment.memberId||'unknown';if(!grouped[key])grouped[key]={amount:0,dates:[]};grouped[key].amount+=Number(payment.amount||0);if(payment.date)grouped[key].dates.push(payment.date)});
  let contributors=Object.entries(grouped).map(([memberId,value])=>({memberId,...value})).filter(item=>item.amount>0).sort((a,b)=>memberName(a.memberId).localeCompare(memberName(b.memberId)));
  let received=contributors.reduce((sum,item)=>sum+item.amount,0),perMember=Number(contribution.amount||0);
  document.getElementById('contributionDetailTitle').textContent=contribution.name;
  document.getElementById('contributionDetailSummary').textContent=`${contributors.length} member${contributors.length===1?'':'s'} contributed · ${money(received)} received`;
  body.innerHTML=contributors.length?`<div class="table-wrap"><table class="data-table contributor-table"><thead><tr><th>Member</th><th>Amount contributed</th><th>Balance</th><th>Latest payment</th></tr></thead><tbody>${contributors.map(item=>`<tr><td><strong>${esc(memberName(item.memberId))}</strong></td><td>${money(item.amount)}</td><td>${money(Math.max(0,perMember-item.amount))}</td><td>${dateFmt(item.dates.sort().at(-1)||'')}</td></tr>`).join('')}</tbody></table></div>`:empty('No member has contributed yet');
  if(!dialog.open)dialog.showModal();
}
function decorateMeetingTemplate(){
  let template=document.querySelector('#view .editable-template[data-template="schedule"]'),wrap=template?.querySelector('.table-wrap');
  if(!wrap||template.querySelector('[data-add-agenda-row]'))return;
  let button=document.createElement('button');button.type='button';button.className='button ghost add-agenda-row';button.dataset.addAgendaRow='';button.textContent='＋ Add activity line';
  button.onclick=()=>{let body=template.querySelector('tbody'),row=document.createElement('tr'),index=body.rows.length;row.innerHTML=Array.from({length:6},(_,cell)=>`<td contenteditable="true" data-cell="${index},${cell}"></td>`).join('');body.appendChild(row);row.cells[0].focus();};
  wrap.insertAdjacentElement('afterend',button);
}
async function loadDesignThumbnails(){
  designPreviewUrls.forEach(url=>URL.revokeObjectURL(url));designPreviewUrls=[];
  let cards=[...document.querySelectorAll('#view .design-card')];
  await Promise.all(cards.map(async card=>{
    let id=card.querySelector('[data-edit="design"]')?.dataset.id,design=state.designs.find(item=>item.id===id),thumb=card.querySelector('.design-thumb');
    if(!design?.filePath||!thumb)return;
    let imageFile=(design.fileType||'').startsWith('image/')||/\.(png|jpe?g|webp|gif)$/i.test(design.fileName||'');
    if(!imageFile)return;
    try{let response=await fetch(`${SUPABASE_URL}/storage/v1/object/authenticated/design-files/${storagePath(design.filePath)}`,{headers:{apikey:SUPABASE_KEY,Authorization:`Bearer ${cloudSession?.access_token||SUPABASE_KEY}`}});if(!response.ok)throw new Error('Preview unavailable');let blob=await response.blob(),url=URL.createObjectURL(blob);designPreviewUrls.push(url);let image=document.createElement('img');image.src=url;image.alt=`${design.category||'Design'} preview`;image.loading='lazy';thumb.replaceChildren(image);thumb.classList.add('has-image')}catch{thumb.title='Sign in to preview this design'}
  }));
}
function decorateDesignShareButtons(){
  document.querySelectorAll('#view .design-card').forEach(card=>{
    let edit=card.querySelector('[data-edit="design"]'),actions=card.querySelector('.actions'),design=state.designs.find(item=>item.id===edit?.dataset.id);
    if(!design?.filePath||!actions||actions.querySelector('[data-share-design]'))return;
    let button=document.createElement('button');button.type='button';button.className='button small ghost';button.dataset.shareDesign=design.id;button.textContent='Share';button.setAttribute('aria-label',`Share ${design.fileName||'design'}`);
    button.onclick=()=>shareDesignFile(design.id,button);actions.insertBefore(button,actions.firstChild);
  });
}
async function shareDesignFile(recordId,button){
  let design=state.designs.find(item=>item.id===recordId);if(!design?.filePath){toast('No file has been uploaded for this design');return}
  let originalText=button?.textContent;if(button){button.disabled=true;button.textContent='Preparing…'}
  try{
    let response=await fetch(`${SUPABASE_URL}/storage/v1/object/authenticated/design-files/${storagePath(design.filePath)}`,{headers:{apikey:SUPABASE_KEY,Authorization:`Bearer ${cloudSession?.access_token||SUPABASE_KEY}`}});if(!response.ok)throw new Error('Could not prepare this design for sharing');
    let blob=await response.blob(),fileName=design.fileName||`illuminate-design.${(blob.type.split('/')[1]||'bin').replace('jpeg','jpg')}`,file=new File([blob],fileName,{type:design.fileType||blob.type||'application/octet-stream'}),title=design.memberId?memberName(design.memberId):(design.title||'Illuminate design');
    if(navigator.share&&(!navigator.canShare||navigator.canShare({files:[file]}))){await navigator.share({title,text:`${title} · ${dateFmt(design.date)}`,files:[file]});toast('Design shared')}
    else{let url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=fileName;link.click();setTimeout(()=>URL.revokeObjectURL(url),1500);toast('Sharing is unavailable here, so the design was downloaded')}
  }catch(error){if(error?.name!=='AbortError')toast(error?.message||'Could not share this design')}
  finally{if(button){button.disabled=false;button.textContent=originalText}}
}
function journeyValue(member){return /^Level [0-4]$/.test(member.journeyLevel||'')?member.journeyLevel:'Level 0'}
function memberGrowthCounts(){let journey=Object.fromEntries([0,1,2,3,4].map(level=>[`Level ${level}`,state.members.filter(member=>journeyValue(member)===`Level ${level}`).length]));return {journey,prayerSchool:state.members.filter(member=>member.prayerSchool==='Yes').length,married:state.members.filter(member=>member.maritalStatus==='Married').length,single:state.members.filter(member=>member.maritalStatus==='Single').length}}
function memberDevelopmentMetrics(){let counts=memberGrowthCounts();return `<section class="card member-growth-card"><div class="card-head"><div><h3>Member growth profile</h3><p>The Journey, Prayer School and marital status</p></div><button class="button small ghost right" data-page-jump="members">View members</button></div><div class="member-growth-metrics">${[0,1,2,3,4].map(level=>`<div class="member-growth-stat"><span>The Journey</span><strong>${counts.journey[`Level ${level}`]}</strong><small>Level ${level}</small></div>`).join('')}<div class="member-growth-stat accent"><span>Prayer School</span><strong>${counts.prayerSchool}</strong><small>Passed</small></div><div class="member-growth-stat"><span>Marital status</span><strong>${counts.married}</strong><small>Married</small></div><div class="member-growth-stat"><span>Marital status</span><strong>${counts.single}</strong><small>Single</small></div></div></section>`}
const dashboardBeforeMemberGrowth=views.dashboard;
views.dashboard=()=>dashboardBeforeMemberGrowth()+memberDevelopmentMetrics();
views.members=()=>`${tools('Search members…','member',['All status','Active','Inactive'])}<div class="card"><div class="card-head"><div><h3>Member directory</h3><p>${state.members.length} people recorded</p></div><button class="button small ghost right" id="csvMembers">↓ CSV export</button></div><div class="table-wrap"><table class="data-table member-directory-table"><thead><tr><th>Member</th><th>Contact</th><th>Sub-unit</th><th>Birthday</th><th>Growth</th><th>DCC & personal</th><th>Skill level</th><th>Status</th><th></th></tr></thead><tbody>${state.members.map(member=>`<tr data-search="${esc(Object.values(member).join(' ').toLowerCase())}" data-status="${member.status}"><td><div class="person"><span class="person-badge">${initials(member.name)}</span><div><strong>${esc(member.name)}</strong><small>${esc(member.email)}</small></div></div></td><td>${esc(member.phone||'—')}</td><td>${esc(member.subunit||'Member')}</td><td>${dateFmt(member.birthday,{day:'numeric',month:'short'})}</td><td><strong>${journeyValue(member)}</strong><br><small>Prayer School: ${member.prayerSchool==='Yes'?'Yes':'No'}</small></td><td><strong>${esc(member.maritalStatus||'Not specified')}</strong><br><small>Joined: ${member.joinDcc?dateFmt(member.joinDcc,{month:'short',year:'numeric'}):'Not recorded'} · ${esc(member.occupation||'Occupation not recorded')}</small></td><td><strong>${esc(member.skill||'—')}</strong><br><small>${esc(member.skillLevel||'—')}</small></td><td><span class="pill ${(member.status||'Inactive').toLowerCase()}">${esc(member.status||'Inactive')}</span></td>${rowActions('member',member.id)}</tr>`).join('')||`<tr><td colspan="9">${empty('No members yet')}</td></tr>`}</tbody></table></div></div><div style="margin-top:18px">${skillsCard()}</div>`;
csvMembers=function(){let cols=['Name','Phone','Email','Birthday','Status','Sub-unit','The Journey Level','Prayer School','Joined DCC','Marital Status','Occupation','Skill','Skill Level','Notes'],keys=['name','phone','email','birthday','status','subunit','journeyLevel','prayerSchool','joinDcc','maritalStatus','occupation','skill','skillLevel','notes'],q=value=>'"'+String(value??'').replace(/"/g,'""')+'"';download(`illuminate-members-${new Date().toISOString().slice(0,10)}.csv`,[cols.map(q).join(','),...state.members.map(member=>keys.map(key=>q(key==='journeyLevel'?journeyValue(member):member[key])).join(','))].join('\r\n'),'text/csv;charset=utf-8');toast('Members CSV downloaded')};
printDashboard=function(){let summary=metrics(),growth=memberGrowthCounts(),contributionRows=state.contributionTypes.map(item=>{let expected=Number(item.amount)*state.members.length,received=state.payments.filter(payment=>payment.typeId===item.id).reduce((sum,payment)=>sum+Number(payment.amount),0);return `<tr><td>${esc(item.name)}</td><td>${money(expected)}</td><td>${money(received)}</td><td>${money(expected-received)}</td><td>${expected?Math.round(received/expected*100):0}%</td></tr>`}).join(''),skillLevels=['Beginner','Intermediate','Advanced'],skillRows=['General schedule','Scripture Projection','using VMIX'].map(skill=>`<tr><td>${skill}</td>${skillLevels.map(level=>`<td>${state.members.filter(member=>member.skill===skill&&member.skillLevel===level).length}</td>`).join('')}<td><b>${state.members.filter(member=>member.skill===skill).length}</b></td></tr>`).join(''),growthRows=[0,1,2,3,4].map(level=>`<tr><td>The Journey — Level ${level}</td><td>${growth.journey[`Level ${level}`]}</td></tr>`).join('')+`<tr><td>Passed Prayer School</td><td>${growth.prayerSchool}</td></tr><tr><td>Married members</td><td>${growth.married}</td></tr><tr><td>Single members</td><td>${growth.single}</td></tr>`,html=`<!doctype html><html><head><title>Illuminate Dashboard Report</title><style>@page{size:A4 portrait;margin:14mm}body{font-family:Arial;color:#172a46}header{border-bottom:3px solid #d7a928;margin-bottom:20px}h1,h2{font-family:Georgia}h2{margin-top:22px}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.metric{border:1px solid #dfe4ea;padding:12px}.metric b{display:block;font-size:23px;margin-top:6px}table{width:100%;border-collapse:collapse;margin-top:10px;break-inside:avoid}th,td{border:1px solid #dfe4ea;padding:8px;text-align:left;font-size:10px}th{background:#172a46;color:#fff}.no-print{margin-bottom:12px}@media print{.no-print{display:none}}</style></head><body><button class="no-print" onclick="print()">Print / Save PDF</button><header><small>DAVID'S CHRISTIAN CENTER · ILLUMINATE DEPARTMENT</small><h1>Dashboard Report</h1><p>${new Date().toLocaleDateString('en-NG',{dateStyle:'long'})}</p></header><div class="metrics"><div class="metric">Total members<b>${state.members.length}</b></div><div class="metric">Active members<b>${summary.active}</b></div><div class="metric">Inactive members<b>${summary.inactive}</b></div><div class="metric">Active contributions<b>${state.contributionTypes.filter(item=>item.status==='Active').length}</b></div><div class="metric">Trainings<b>${summary.training}</b></div><div class="metric">Prayer School passed<b>${growth.prayerSchool}</b></div></div><h2>Member growth profile</h2><table><thead><tr><th>Member metric</th><th>Count</th></tr></thead><tbody>${growthRows}</tbody></table><h2>Contribution progress</h2><table><thead><tr><th>Contribution</th><th>Expected</th><th>Received</th><th>Outstanding</th><th>Progress</th></tr></thead><tbody>${contributionRows}</tbody></table><h2>Skill matrix</h2><table><thead><tr><th>Skill</th>${skillLevels.map(level=>`<th>${level}</th>`).join('')}<th>Total</th></tr></thead><tbody>${skillRows}</tbody></table></body></html>`;let reportWindow=open('','_blank');reportWindow.document.write(html);reportWindow.document.close();setTimeout(()=>reportWindow.print(),350)};
state.attendance=Array.isArray(state.attendance)?state.attendance:[];
state.weeklySupervisors=Array.isArray(state.weeklySupervisors)?state.weeklySupervisors:[];
state.tasks=Array.isArray(state.tasks)?state.tasks:[];
let activityTab='calendar',attendanceActivityId=null;

function weekKey(date){let value=new Date(date);value.setHours(0,0,0,0);value.setDate(value.getDate()-value.getDay());return localDateIso(value)}
function handlerForWeek(weekStart){let assigned=state.weeklyHandlers.find(item=>item.weekStart===weekStart);if(!assigned){let previousMonday=new Date(`${weekStart}T12:00:00`);previousMonday.setDate(previousMonday.getDate()+1);assigned=state.weeklyHandlers.find(item=>item.weekStart===localDateIso(previousMonday))}return assigned?.admin||defaultWeeklyHandler(weekStart)}
function supervisorFor(date){return handlerForWeek(weekForDate(localDateIso(date)))}
function saveWeeklySupervisor(weekStart,admin){let record=state.weeklyHandlers.find(item=>item.weekStart===weekStart);if(record)Object.assign(record,{admin,updatedAt:new Date().toISOString()});else state.weeklyHandlers.push({id:id('wh'),weekStart,admin,updatedAt:new Date().toISOString()});save(`${admin} is handling the week`)}
function attendanceFor(activityId){return state.attendance.find(item=>item.activityId===activityId)}
function legacyActivityCalendarView(){
  let types=['All','Training','Outreach','Event','Evangelism','Meeting','Hangout'],y=calendarDate.getFullYear(),month=calendarDate.getMonth(),first=new Date(y,month,1),last=new Date(y,month+1,0),start=new Date(y,month,1-first.getDay()),end=new Date(y,month,last.getDate()+(6-last.getDay())),weeks=[];
  for(let cursor=new Date(start);cursor<=end;cursor.setDate(cursor.getDate()+7)){
    let weekStart=new Date(cursor),key=weekKey(weekStart),days=[];
    for(let offset=0;offset<7;offset++){let date=new Date(weekStart);date.setDate(date.getDate()+offset);let iso=date.toISOString().slice(0,10),items=state.activities.filter(activity=>activity.date===iso&&(activityTypeFilter==='All'||activity.type===activityTypeFilter)).sort((a,b)=>(a.time||'').localeCompare(b.time||'')),muted=date.getMonth()!==month;
      days.push(`<div class="calendar-day ${muted?'muted':''}"><button class="calendar-date-add" data-calendar-date="${iso}" aria-label="Add activity on ${dateFmt(iso)}"><b>${date.getDate()}</b><i>＋ Add</i></button><div class="calendar-events">${items.map(activity=>{let record=attendanceFor(activity.id),count=record?.memberIds?.length||0;return `<button class="calendar-event" data-open-attendance="${activity.id}"><strong>${esc(activity.time||'')}</strong> ${esc(activity.title)}<small>${record?`${count} present`:'Attendance'}</small></button>`}).join('')}</div></div>`)}
    weeks.push(`<section class="calendar-week"><div class="week-supervisor"><div><strong>Week of ${dateFmt(key,{day:'numeric',month:'short'})}</strong><small>Activity supervisor</small></div><select data-week-supervisor="${key}" aria-label="Supervisor for week of ${dateFmt(key)}"><option value="">Not assigned</option>${state.members.filter(member=>!['Inactive','On Leave','Exited'].includes(member.status)).map(member=>`<option value="${member.id}" ${supervisorFor(weekStart)===member.id?'selected':''}>${esc(member.name)}</option>`).join('')}</select></div><div class="calendar-grid">${days.join('')}</div></section>`)}
  return `<div class="activity-tabs"><button class="activity-tab active" data-activity-tab="calendar">Activities & calendar</button><button class="activity-tab" data-activity-tab="tasks">Tasks / To-do</button></div><div class="calendar-toolbar"><select class="filter" id="activityTypeFilter">${types.map(type=>`<option ${type===activityTypeFilter?'selected':''}>${type}</option>`).join('')}</select><span class="spacer"></span><button class="button ghost" data-calendar-nav="-1">‹</button><h2>${first.toLocaleDateString('en-NG',{month:'long',year:'numeric'})}</h2><button class="button ghost" data-calendar-nav="1">›</button><button class="button primary" data-add="activity">＋ Add activity</button></div><div class="calendar calendar-with-supervisors"><div class="calendar-weekdays">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(day=>`<span>${day}</span>`).join('')}</div>${weeks.join('')}</div>`
}
function taskView(){return `<div class="activity-tabs"><button class="activity-tab" data-activity-tab="calendar">Activities & calendar</button><button class="activity-tab active" data-activity-tab="tasks">Tasks / To-do</button></div><div class="page-tools"><button class="button primary" data-add="task">＋ Add task</button></div><div class="card"><div class="card-head"><div><h3>Tasks</h3><p>Assignments, deadlines and completion</p></div></div><div class="table-wrap"><table class="data-table task-table"><thead><tr><th>Task</th><th>Assignee</th><th>Deadline</th><th>Status</th><th>Completion</th><th></th></tr></thead><tbody>${state.tasks.slice().sort((a,b)=>(a.deadline||'').localeCompare(b.deadline||'')).map(task=>{let completion=Math.max(0,Math.min(100,Number(task.completion)||0));return `<tr><td><strong>${esc(task.title)}</strong><br><small>${esc(task.notes||'')}</small></td><td>${esc(memberName(task.assigneeId))}</td><td>${dateFmt(task.deadline)}</td><td><span class="pill ${(task.status||'In Progress').toLowerCase().replaceAll(' ','-')}">${esc(task.status||'In Progress')}</span></td><td><strong>${completion}%</strong><div class="progress"><i style="width:${completion}%"></i></div></td>${rowActions('task',task.id)}</tr>`}).join('')||`<tr><td colspan="6">${empty('No tasks yet')}</td></tr>`}</tbody></table></div></div>`}
views.activities=()=>activityTab==='tasks'?taskView():activityCalendarView();

views.designs=()=>`${tools('Search designs…','design',['All status','Pending','Close to post date','Past'])}<div class="design-grid">${state.designs.slice().sort((a,b)=>(a.date||'').localeCompare(b.date||'')).map(design=>{let status=designStatus(design),title=design.memberId?memberName(design.memberId):design.title;return `<article class="design-card" data-search="${esc(Object.values(design).join(' ').toLowerCase())}" data-status="${status}"><div class="design-thumb"><span>${esc(design.category)}</span></div><div class="design-info"><span class="pill ${status.toLowerCase().replaceAll(' ','-')}">${status}</span><h4>${esc(title||'Untitled design')}</h4><p>${dateFmt(design.date)} · ${esc(design.category)}</p><div class="design-file"><span>${design.fileName?'▣':'○'}</span><div><strong>${esc(design.fileName||'No file uploaded')}</strong><small>${design.fileSize?formatBytes(design.fileSize):'Edit this design to upload a file'}</small></div></div><div class="actions">${design.filePath?`<button class="button small gold" data-download-design="${design.id}">Download</button>`:''}<button class="button small" data-edit="design" data-id="${design.id}">Edit</button><button class="button small danger" data-delete="design" data-id="${design.id}">Delete</button></div></div></article>`}).join('')||empty('No designs yet')}</div>`;

views.members=()=>`${tools('Search members…','member',['All status','New','Active','Inactive','On Leave','Exited'])}<div class="card"><div class="card-head"><div><h3>Member directory</h3><p>${state.members.length} people recorded</p></div><button class="button small ghost right" id="csvMembers">↓ CSV export</button></div><div class="table-wrap"><table class="data-table member-directory-table"><thead><tr><th>Member</th><th>Contact</th><th>Sub-unit</th><th>Birthday</th><th>Growth</th><th>DCC & personal</th><th>Skill level</th><th>Status</th><th></th></tr></thead><tbody>${state.members.map(member=>`<tr data-search="${esc(Object.values(member).join(' ').toLowerCase())}" data-status="${member.status}"><td><button class="member-name-button" data-member-profile="${member.id}"><span class="person-badge">${initials(member.name)}</span><span><strong>${esc(member.name)}</strong><small>${esc(member.email)}</small></span></button></td><td>${esc(member.phone||'—')}</td><td>${esc(member.subunit||'Member')}</td><td>${dateFmt(member.birthday,{day:'numeric',month:'short'})}</td><td><strong>${journeyValue(member)}</strong><br><small>Prayer School: ${member.prayerSchool==='Yes'?'Yes':'No'}</small></td><td><strong>${esc(member.maritalStatus||'Not specified')}</strong><br><small>Joined: ${member.joinDcc?dateFmt(member.joinDcc,{month:'short',year:'numeric'}):'Not recorded'} · ${esc(member.occupation||'Occupation not recorded')}</small></td><td><strong>${esc(member.skill||'—')}</strong><br><small>${esc(member.skillLevel||'—')}</small></td><td><span class="pill ${(member.status||'Inactive').toLowerCase().replaceAll(' ','-')}">${esc(member.status||'Inactive')}</span></td>${rowActions('member',member.id)}</tr>`).join('')||`<tr><td colspan="9">${empty('No members yet')}</td></tr>`}</tbody></table></div></div><div style="margin-top:18px">${skillsCard()}</div>`;

function openAttendance(activityId){let activity=state.activities.find(item=>item.id===activityId);if(!activity)return;attendanceActivityId=activityId;let record=attendanceFor(activityId),selected=new Set(record?.memberIds||[]);document.getElementById('attendanceTitle').textContent=activity.title;document.getElementById('attendanceSummary').textContent=`${dateFmt(activity.date)} · ${activity.time||'Time not set'} · ${activity.venue||'Venue not set'}`;document.getElementById('attendanceBody').innerHTML=`<div class="attendance-tools"><input id="attendanceMemberSearch" class="search" placeholder="Search members…"><span><strong id="attendanceSelectedCount">${selected.size}</strong> selected</span></div><div class="attendance-list">${state.members.filter(member=>!['Exited'].includes(member.status)).map(member=>`<label data-attendance-name="${esc(member.name.toLowerCase())}"><input type="checkbox" value="${member.id}" ${selected.has(member.id)?'checked':''}><span class="person-badge">${initials(member.name)}</span><span><strong>${esc(member.name)}</strong><small>${esc(member.subunit)} · ${esc(member.status)}</small></span></label>`).join('')}</div>`;let dialog=document.getElementById('attendanceDialog');dialog.showModal();let search=document.getElementById('attendanceMemberSearch');search.oninput=()=>document.querySelectorAll('[data-attendance-name]').forEach(row=>row.hidden=!row.dataset.attendanceName.includes(search.value.toLowerCase()));dialog.querySelectorAll('input[type="checkbox"]').forEach(input=>input.onchange=()=>document.getElementById('attendanceSelectedCount').textContent=dialog.querySelectorAll('input[type="checkbox"]:checked').length)}
function saveAttendance(){let memberIds=[...document.querySelectorAll('#attendanceBody input[type="checkbox"]:checked')].map(input=>input.value),activity=state.activities.find(item=>item.id===attendanceActivityId),record=attendanceFor(attendanceActivityId);if(record){record.memberIds=memberIds;record.updatedAt=new Date().toISOString()}else state.attendance.push({id:id('n'),activityId:attendanceActivityId,date:activity?.date||'',memberIds,updatedAt:new Date().toISOString()});document.getElementById('attendanceDialog').close();save('Attendance saved')}
function openAttendancePicker(){let dialog=document.getElementById('detailDialog');document.getElementById('detailEyebrow').textContent='ATTENDANCE';document.getElementById('detailTitle').textContent='Choose an activity';document.getElementById('detailBody').innerHTML=`<div class="history-list">${state.activities.slice().sort((a,b)=>(b.date||'').localeCompare(a.date||'')).map(activity=>`<button data-open-attendance="${activity.id}"><span><strong>${esc(activity.title)}</strong><small>${dateFmt(activity.date)} · ${esc(activity.type)}</small></span><b>${attendanceFor(activity.id)?.memberIds?.length||0} present</b></button>`).join('')||empty('No activities available')}</div>`;dialog.showModal();dialog.querySelectorAll('[data-open-attendance]').forEach(button=>button.onclick=()=>{dialog.close();openAttendance(button.dataset.openAttendance)})}
function memberAttendanceStats(memberId){let records=state.attendance.filter(record=>state.activities.some(activity=>activity.id===record.activityId));return {present:records.filter(record=>record.memberIds?.includes(memberId)).length,missed:records.filter(record=>!record.memberIds?.includes(memberId)).length,total:records.length}}
function openMemberProfile(memberId){let member=state.members.find(item=>item.id===memberId);if(!member)return;let stats=memberAttendanceStats(memberId),payments=state.payments.filter(item=>item.memberId===memberId),tasks=state.tasks.filter(item=>item.assigneeId===memberId),attendance=state.attendance.filter(item=>item.memberIds?.includes(memberId)).map(item=>state.activities.find(activity=>activity.id===item.activityId)).filter(Boolean),assignments=state.rosters.filter(item=>(item.assignments||'').toLowerCase().includes((member.name||'').toLowerCase()));document.getElementById('detailEyebrow').textContent='MEMBER PROFILE';document.getElementById('detailTitle').textContent=member.name;document.getElementById('detailBody').innerHTML=`<div class="profile-summary"><div><span>Status</span><strong>${esc(member.status)}</strong></div><div><span>Sub-unit</span><strong>${esc(member.subunit)}</strong></div><div><span>Attendance</span><strong>${stats.present}/${stats.total}</strong></div><div><span>Contribution records</span><strong>${payments.length}</strong></div></div><div class="profile-grid"><section><h3>Profile</h3><p>${esc(member.phone||'No phone')}<br>${esc(member.email||'No email')}<br>${journeyValue(member)} · Prayer School: ${esc(member.prayerSchool||'No')}<br>${esc(member.occupation||'Occupation not recorded')}</p></section><section><h3>Tasks</h3>${tasks.map(task=>`<p><strong>${esc(task.title)}</strong><br><small>${esc(task.status)} · ${dateFmt(task.deadline)}</small></p>`).join('')||'<p>No assigned tasks.</p>'}</section><section><h3>Contributions</h3>${payments.map(payment=>`<p><strong>${esc(state.contributionTypes.find(item=>item.id===payment.typeId)?.name||'Contribution')}</strong><br><small>${money(payment.amount)} · ${dateFmt(payment.date)}</small></p>`).join('')||'<p>No payments recorded.</p>'}</section><section><h3>Attendance & assignments</h3><p>${stats.present} present · ${stats.missed} missed</p>${attendance.slice(0,5).map(activity=>`<p><strong>${esc(activity.title)}</strong><br><small>${dateFmt(activity.date)}</small></p>`).join('')}${assignments.map(item=>`<p><strong>${esc(item.event)}</strong><br><small>${dateFmt(item.date)}</small></p>`).join('')||''}</section></div>`;document.getElementById('detailDialog').showModal()}

function missedMeetingAnalysis(){let meetings=state.activities.filter(activity=>activity.type==='Meeting'&&attendanceFor(activity.id)).sort((a,b)=>(a.date||'').localeCompare(b.date||''));return state.members.map(member=>{let currentStreak=0,maxStreak=0,totalMissed=0;meetings.forEach(activity=>{let present=attendanceFor(activity.id)?.memberIds?.includes(member.id);if(present)currentStreak=0;else{currentStreak++;totalMissed++;maxStreak=Math.max(maxStreak,currentStreak)}});return {member,maxStreak,totalMissed}}).filter(item=>item.maxStreak>=2).sort((a,b)=>b.maxStreak-a.maxStreak)}
function attendanceCsv(){let rows=[['Activity','Type','Date','Member','Present']];state.activities.slice().sort((a,b)=>(a.date||'').localeCompare(b.date||'')).forEach(activity=>{let record=attendanceFor(activity.id);if(!record)return;state.members.forEach(member=>rows.push([activity.title,activity.type,activity.date,member.name,record.memberIds?.includes(member.id)?'Yes':'No']))});let quote=value=>'"'+String(value??'').replaceAll('"','""')+'"';download(`illuminate-attendance-${new Date().toISOString().slice(0,10)}.csv`,rows.map(row=>row.map(quote).join(',')).join('\r\n'),'text/csv;charset=utf-8');toast('Attendance CSV downloaded')}
function printAttendance(){let rows=state.activities.slice().sort((a,b)=>(b.date||'').localeCompare(a.date||'')).filter(activity=>attendanceFor(activity.id)).map(activity=>{let record=attendanceFor(activity.id);return `<h2>${esc(activity.title)}</h2><p>${dateFmt(activity.date)} · ${esc(activity.type)} · ${record.memberIds.length} present</p><table><thead><tr><th>Member</th><th>Sub-unit</th><th>Present</th></tr></thead><tbody>${state.members.map(member=>`<tr><td>${esc(member.name)}</td><td>${esc(member.subunit)}</td><td>${record.memberIds.includes(member.id)?'Yes':'No'}</td></tr>`).join('')}</tbody></table>`}).join(''),html=`<!doctype html><html><head><title>Attendance Report</title><style>@page{size:A4 portrait;margin:14mm}body{font-family:Arial;color:#172a46}header{border-bottom:3px solid #d7a928}h1,h2{font-family:Georgia}h2{margin:24px 0 4px}table{width:100%;border-collapse:collapse;break-inside:avoid}th,td{border:1px solid #dfe4ea;padding:7px;text-align:left;font-size:10px}th{background:#172a46;color:#fff}.no-print{margin-bottom:12px}@media print{.no-print{display:none}}</style></head><body><button class="no-print" onclick="print()">Print / Save PDF</button><header><small>DAVID'S CHRISTIAN CENTER · ILLUMINATE DEPARTMENT</small><h1>Activity Attendance Report</h1><p>${new Date().toLocaleDateString('en-NG',{dateStyle:'long'})}</p></header>${rows||'<p>No attendance has been recorded.</p>'}</body></html>`;let win=open('','_blank');win.document.write(html);win.document.close();setTimeout(()=>win.print(),350)}
views.reports=()=>{let analysis=missedMeetingAnalysis();return `<div class="report-analysis"><div class="card"><div class="card-head"><div><h3>Attendance analysis</h3><p>Members who missed at least two recorded meetings consecutively</p></div></div><div class="card-body">${analysis.map(item=>`<div class="analysis-row"><button data-member-profile="${item.member.id}"><strong>${esc(item.member.name)}</strong><small>${esc(item.member.subunit)}</small></button><span><b>${item.maxStreak}</b> consecutive · ${item.totalMissed} total missed</span></div>`).join('')||empty('No consecutive meeting absences found')}</div></div></div><div class="report-options" style="margin-top:18px"><div class="report-option"><div class="report-icon">▥</div><div><h4>Dashboard report</h4><p>Metrics, contributions and member growth</p></div><button class="button small primary" data-report="dashboard">Print / PDF</button></div><div class="report-option"><div class="report-icon">CSV</div><div><h4>Members table</h4><p>All member profile fields</p></div><button class="button small primary" id="csvMembers">Download</button></div><div class="report-option"><div class="report-icon">✓</div><div><h4>Attendance CSV</h4><p>Attendance by activity and member</p></div><button class="button small primary" id="attendanceCsv">Download</button></div><div class="report-option"><div class="report-icon">PDF</div><div><h4>Attendance PDF</h4><p>Printable activity attendance registers</p></div><button class="button small primary" id="attendancePdf">Print / PDF</button></div><div class="report-option"><div class="report-icon">JSON</div><div><h4>Complete data backup</h4><p>Portable copy of every record</p></div><button class="button small primary" id="reportBackup">Download</button></div><div class="report-option"><div class="report-icon">↥</div><div><h4>Restore backup</h4><p>Replace records from a JSON backup</p></div><label class="button small primary file-label">Choose file<input id="reportRestore" type="file" accept="application/json"></label></div></div>`}

function showActivityHistory(){let past=state.activities.filter(activity=>activity.date<=new Date().toISOString().slice(0,10)).sort((a,b)=>(b.date||'').localeCompare(a.date||''));document.getElementById('detailEyebrow').textContent='ACTIVITY HISTORY';document.getElementById('detailTitle').textContent='Past activities';document.getElementById('detailBody').innerHTML=`<div class="history-list">${past.map(activity=>`<button data-open-attendance="${activity.id}"><span><strong>${esc(activity.title)}</strong><small>${dateFmt(activity.date)} · ${esc(activity.type)} · ${esc(activity.venue||'Venue not set')}</small></span><b>${attendanceFor(activity.id)?.memberIds?.length||0} present</b></button>`).join('')||empty('No past activities')}</div>`;let dialog=document.getElementById('detailDialog');dialog.showModal();dialog.querySelectorAll('[data-open-attendance]').forEach(button=>button.onclick=()=>{dialog.close();openAttendance(button.dataset.openAttendance)})}
function searchMemberRecords(query){let value=query.trim().toLowerCase();if(value.length<2)return [];return state.members.filter(member=>(member.name||'').toLowerCase().includes(value)).slice(0,8)}
function renderGlobalSearch(){let input=document.getElementById('globalSearch'),results=document.getElementById('globalSearchResults'),matches=searchMemberRecords(input.value);if(input.value.trim().length<2){results.hidden=true;return}results.innerHTML=matches.map(member=>{let stats=memberAttendanceStats(member.id),tasks=state.tasks.filter(item=>item.assigneeId===member.id).length,payments=state.payments.filter(item=>item.memberId===member.id).length;return `<button data-member-profile="${member.id}"><span class="person-badge">${initials(member.name)}</span><span><strong>${esc(member.name)}</strong><small>${esc(member.subunit)} · ${tasks} tasks · ${payments} payments · ${stats.present}/${stats.total} attendance</small></span></button>`}).join('')||'<p class="search-empty">No matching member</p>';results.hidden=false;results.querySelectorAll('[data-member-profile]').forEach(button=>button.onclick=()=>{results.hidden=true;input.value='';openMemberProfile(button.dataset.memberProfile)})}

const previousPostRenderEnhancements=postRenderEnhancements;
postRenderEnhancements=function(){previousPostRenderEnhancements();document.querySelectorAll('[data-activity-tab]').forEach(button=>button.onclick=()=>{activityTab=button.dataset.activityTab;render()});document.querySelectorAll('[data-open-attendance]').forEach(button=>button.onclick=event=>{event.stopPropagation();openAttendance(button.dataset.openAttendance)});document.querySelectorAll('[data-week-supervisor]').forEach(select=>select.onchange=()=>saveWeeklySupervisor(select.dataset.weekSupervisor,select.value));document.querySelectorAll('[data-member-profile]').forEach(button=>button.onclick=()=>openMemberProfile(button.dataset.memberProfile));let csv=document.getElementById('attendanceCsv'),pdf=document.getElementById('attendancePdf');if(csv)csv.onclick=attendanceCsv;if(pdf)pdf.onclick=printAttendance};

document.getElementById('attendanceClose').onclick=()=>document.getElementById('attendanceDialog').close();
document.getElementById('attendanceCancel').onclick=()=>document.getElementById('attendanceDialog').close();
document.getElementById('attendanceSave').onclick=saveAttendance;
document.getElementById('detailClose').onclick=()=>document.getElementById('detailDialog').close();
let activityHistoryButton=document.getElementById('activityHistoryButton');if(activityHistoryButton)activityHistoryButton.onclick=showActivityHistory;
document.getElementById('globalSearch').oninput=renderGlobalSearch;
document.getElementById('globalSearch').onfocus=renderGlobalSearch;
document.getElementById('quickAddButton').onclick=event=>{event.stopPropagation();let menu=document.getElementById('quickAddMenu'),showing=menu.hidden;menu.hidden=!showing;event.currentTarget.setAttribute('aria-expanded',String(showing))};
document.getElementById('quickAddMenu').onclick=event=>{let button=event.target.closest('[data-quick-add]');if(!button)return;document.getElementById('quickAddMenu').hidden=true;if(button.dataset.quickAdd==='attendance')openAttendancePicker();else if(button.dataset.quickAdd==='weekly')openWeeklyForm();else openForm(button.dataset.quickAdd)};
document.addEventListener('click',event=>{if(!event.target.closest('.header-menu-wrap'))document.getElementById('quickAddMenu').hidden=true;if(!event.target.closest('.header-search-wrap'))document.getElementById('globalSearchResults').hidden=true});

state.weeklyActions=Array.isArray(state.weeklyActions)?state.weeklyActions:[];
state.weeklyClosures=Array.isArray(state.weeklyClosures)?state.weeklyClosures:[];
state.weeklyHandlers=Array.isArray(state.weeklyHandlers)?state.weeklyHandlers:[];
let weeklyEditId=null;
const WEEKLY_TYPES=['House Reminder','Reach-out','Update','Schedule Preparation','General Task'];
const WEEKLY_ADMINS=['MaryJane','Eden','Victoria','Tolu'];
const WEEKLY_STATUS={
  'House Reminder':['To Do','In Progress','Done'],
  'Reach-out':['To Do','In Progress','Done'],
  'Update':['To Do','In Progress','Done'],
  'Schedule Preparation':['To Do','In Progress','Done'],
  'General Task':['To Do','In Progress','Done']
};
function localDateIso(date=new Date()){let value=new Date(date),year=value.getFullYear(),month=String(value.getMonth()+1).padStart(2,'0'),day=String(value.getDate()).padStart(2,'0');return `${year}-${month}-${day}`}
function sundayOf(date=new Date()){let value=new Date(date);value.setHours(0,0,0,0);value.setDate(value.getDate()-value.getDay());return value}
function currentWeek(){let start=sundayOf(),end=new Date(start);end.setDate(end.getDate()+6);return {start,end,key:localDateIso(start)}}
function weekForDate(date){return localDateIso(sundayOf(new Date(`${date}T12:00:00`)))}
function legacyWeeklyDone(item){return ['Sent','Completed','Cancelled','Reached'].includes(item.status)}
function weeklyOverdue(item){if(weeklyDone(item)||!item.dueDate)return false;let deadline=new Date(`${item.dueDate}T${item.dueTime||'23:59'}:00`);return deadline<new Date()}
function legacyWeeklyStatusOptions(type){return WEEKLY_STATUS[type]||['Pending','Completed']}
function legacyWeeklyTypeIcon(type){return {'House Reminder':'▣','Meeting':'◎','Schedule':'◷','Update':'↻','Reach-out':'☎'}[type]||'•'}
function moduleLabel(module){return {members:'Members',contributions:'Contributions',activities:'Activities',schedule:'Schedule & Roster',designs:'Designs',reports:'Reports'}[module]||''}
function legacyDefaultWeeklyModule(type){return {'Meeting':'activities','Schedule':'schedule','Update':'members','Reach-out':'members'}[type]||''}
function legacyWeeklyAdminOptions(selected=''){return `<option value="">Unassigned</option>${state.members.filter(member=>!['Inactive','On Leave','Exited'].includes(member.status)).map(member=>`<option value="${member.id}" ${member.id===selected?'selected':''}>${esc(member.name)}</option>`).join('')}`}
function ensureRecurringWeeklyItems(){let week=currentWeek(),sources=new Map();state.weeklyActions.filter(item=>item.recurring&&item.weekStart<week.key).forEach(item=>{let source=item.recurringSourceId||item.id,current=sources.get(source);if(!current||item.weekStart>current.weekStart)sources.set(source,item)});let added=false;sources.forEach((template,source)=>{if(state.weeklyActions.some(item=>item.weekStart===week.key&&(item.recurringSourceId||item.id)===source))return;let original=new Date(`${template.dueDate}T12:00:00`),weekday=original.getDay(),due=new Date(week.start);due.setDate(due.getDate()+weekday);state.weeklyActions.push({...template,id:id('w'),weekStart:week.key,dueDate:localDateIso(due),status:weeklyStatusOptions(template.type)[0],recurringSourceId:source,createdAt:new Date().toISOString()});added=true});if(added){localStorage.setItem(STORAGE_KEY,JSON.stringify(state));queueCloudSync()}}
function legacyWeeklyItems(){ensureRecurringWeeklyItems();return state.weeklyActions.filter(item=>item.weekStart===currentWeek().key).sort((a,b)=>`${a.dueDate||''}T${a.dueTime||''}`.localeCompare(`${b.dueDate||''}T${b.dueTime||''}`))}
function weeklyStats(){let items=weeklyItems(),today=localDateIso(),done=items.filter(weeklyDone).length,overdue=items.filter(weeklyOverdue).length,upcoming=items.filter(item=>!weeklyDone(item)&&!weeklyOverdue(item)&&item.dueDate>=today).length;return {items,total:items.length,done,overdue,upcoming}}
function weekTitle(){let {start,end}=currentWeek(),sameYear=start.getFullYear()===end.getFullYear(),sameMonth=sameYear&&start.getMonth()===end.getMonth(),startLabel=start.toLocaleDateString('en-NG',{day:'numeric',month:'short'}),endLabel=sameMonth?String(end.getDate()):end.toLocaleDateString('en-NG',{day:'numeric',month:'short'}),yearLabel=sameYear?String(end.getFullYear()):`${start.getFullYear()}–${end.getFullYear()}`;return `This Week · ${startLabel}–${endLabel}, ${yearLabel}`}
function defaultWeeklyHandler(weekStart=currentWeek().key){let anchor=new Date('2026-10-04T12:00:00'),week=new Date(`${weekStart}T12:00:00`),offset=Math.round((week-anchor)/604800000),index=((offset%WEEKLY_ADMINS.length)+WEEKLY_ADMINS.length)%WEEKLY_ADMINS.length;return WEEKLY_ADMINS[index]}
function weeklyHandlerName(){return handlerForWeek(currentWeek().key)}
function updateWeeklyHandler(admin){let weekStart=currentWeek().key,record=state.weeklyHandlers.find(item=>item.weekStart===weekStart);if(record)Object.assign(record,{admin,updatedAt:new Date().toISOString()});else state.weeklyHandlers.push({id:id('wh'),weekStart,admin,updatedAt:new Date().toISOString()});save(`${admin} is handling this week`)}
function weeklyItemCard(item){let admin=memberName(item.responsibleId),overdue=weeklyOverdue(item),linked=moduleLabel(item.linkedModule);return `<article class="weekly-item ${weeklyDone(item)?'is-done':''} ${overdue?'is-overdue':''}"><div class="weekly-type-icon">${weeklyTypeIcon(item.type)}</div><div class="weekly-item-main"><div class="weekly-item-title"><span class="weekly-type">${esc(item.type)}</span><h4>${esc(item.title)}</h4>${item.recurring?'<span class="recurring-tag">Weekly</span>':''}</div><p>${esc(item.message||item.notes||'No additional note')}</p><div class="weekly-meta"><span>${esc(admin==='—'?'Unassigned':admin)}</span><span>${dateFmt(item.dueDate,{weekday:'short',day:'numeric',month:'short'})}${item.dueTime?` · ${esc(item.dueTime)}`:''}</span>${overdue?'<strong>Overdue</strong>':''}</div></div><div class="weekly-item-actions"><select data-weekly-status="${item.id}" aria-label="Status for ${esc(item.title)}">${weeklyStatusOptions(item.type).map(status=>`<option ${status===item.status?'selected':''}>${status}</option>`).join('')}</select><div>${item.type==='House Reminder'&&item.message?`<button class="action" data-copy-weekly="${item.id}">Copy message</button>`:''}${linked?`<button class="action" data-weekly-module="${item.linkedModule}">Open ${linked}</button>`:''}<button class="action" data-weekly-followup="${item.id}">Follow-up</button><button class="action" data-weekly-carry="${item.id}">Carry forward</button><button class="action" data-weekly-edit="${item.id}">Edit</button><button class="action danger" data-weekly-delete="${item.id}">Delete</button></div></div></article>`}
function weeklySection(title,subtitle,items){return `<section class="weekly-group"><div class="weekly-group-head"><div><h3>${title}</h3><p>${subtitle}</p></div><span>${items.length}</span></div><div class="weekly-list">${items.map(weeklyItemCard).join('')||`<div class="weekly-empty">Nothing here.</div>`}</div></section>`}
views.week=()=>{let stats=weeklyStats(),closed=state.weeklyClosures.find(item=>item.weekStart===currentWeek().key),handler=weeklyHandlerName();return `<section class="weekly-hero"><div><p class="eyebrow">SUNDAY–SATURDAY OPERATIONS</p><h2>${weekTitle()}</h2><label class="week-handler"><span>Week handled by</span><select id="weeklyHandler" aria-label="Admin handling this week">${WEEKLY_ADMINS.map(admin=>`<option ${admin===handler?'selected':''}>${admin}</option>`).join('')}</select></label><p>${stats.total} Actions · ${stats.done} Done · ${stats.upcoming} Upcoming · ${stats.overdue} Overdue</p></div><div class="weekly-hero-actions">${closed?`<span class="week-closed">Closed ${dateFmt(closed.closedAt?.slice(0,10))}</span>`:''}<button class="button ghost" id="carryWeek">Carry Forward</button><button class="button ghost" id="closeWeek">Close Week</button><button class="button gold" id="addWeeklyItem">＋ Add Item</button></div></section><div class="weekly-summary"><div><span>Actions</span><strong>${stats.total}</strong></div><div><span>Done</span><strong>${stats.done}</strong></div><div><span>Upcoming</span><strong>${stats.upcoming}</strong></div><div class="${stats.overdue?'alert':''}"><span>Overdue</span><strong>${stats.overdue}</strong></div></div><section class="weekly-group weekly-all-items"><div class="weekly-group-head"><div><h3>Weekly actions</h3><p>All items for the week, ordered by date and time</p></div><span>${stats.total}</span></div><div class="weekly-list">${stats.items.map(weeklyItemCard).join('')||'<div class="weekly-empty"><strong>No items added for this week yet.</strong><span>Use + Add Item to create the first action.</span></div>'}</div></section>`}
function legacyWeeklyDashboardCard(){let stats=weeklyStats(),urgent=stats.items.filter(item=>!weeklyDone(item)&&(weeklyOverdue(item)||item.dueDate===localDateIso())).slice(0,3);return `<section class="card this-week-card"><div class="card-head"><div><p class="eyebrow">WEEKLY OPERATIONS</p><h3>${weekTitle()}</h3></div><button class="button small primary right" data-page-jump="week">Open This Week</button></div><div class="this-week-body"><div class="this-week-counts"><div><strong>${stats.total}</strong><span>Actions</span></div><div><strong>${stats.done}</strong><span>Done</span></div><div><strong>${stats.upcoming}</strong><span>Upcoming</span></div><div class="${stats.overdue?'alert':''}"><strong>${stats.overdue}</strong><span>Overdue</span></div></div><div class="this-week-urgent">${urgent.map(item=>`<button data-page-jump="week"><span class="weekly-type">${esc(item.type)}</span><strong>${esc(item.title)}</strong><small>${weeklyOverdue(item)?'Overdue':`Due ${esc(item.dueTime||'today')}`}</small></button>`).join('')||'<p>No urgent items today.</p>'}</div></div></section>`}
const dashboardBeforeWeeklyWorkflow=views.dashboard;
views.dashboard=()=>{normalizeOperationalData();let content=dashboardBeforeWeeklyWorkflow().replace('<p>Your department at a glance — everything updates as your records change.</p>','').replace(/<div class="card"><div class="card-head"><div><h3>Next activities<\/h3>[\s\S]*?<\/div><\/div>(?=<div class="card"><div class="card-head"><div><h3>Skill matrix<\/h3>)/,'').replace('<section class="grid-2 grid-even" style="margin-top:18px"><div class="card"><div class="card-head"><div><h3>Skill matrix</h3>','<section style="margin-top:18px"><div class="card"><div class="card-head"><div><h3>Skill matrix</h3>'),heroEnd=content.indexOf('</section>')+'</section>'.length;if(heroEnd<'</section>'.length)return weeklyDashboardCard()+content;let hero=content.slice(0,heroEnd).replace(/<\/div><\/section>$/,`<span class="hero-week-admin">Week admin · ${esc(weeklyHandlerName())}</span></div></section>`);return hero+weeklyDashboardCard()+content.slice(heroEnd)};
function fillWeeklyStatus(type,selected){let select=document.getElementById('weeklyStatus');select.innerHTML=weeklyStatusOptions(type).map(status=>`<option ${status===selected?'selected':''}>${status}</option>`).join('')}
function legacySetWeeklyFormVisibility(type){document.querySelector('.weekly-venue-field').hidden=type!=='Meeting';document.querySelector('.weekly-actions-field').hidden=type!=='Meeting';document.querySelector('.weekly-message-field label').textContent=type==='House Reminder'?'Message / note':type==='Reach-out'?'Reason for contact':'Description / note';if(!document.querySelector('[name="linkedModule"]').value)document.querySelector('[name="linkedModule"]').value=defaultWeeklyModule(type)}
function legacyOpenWeeklyForm(recordId=null,preset={}){weeklyEditId=recordId;let record=recordId?state.weeklyActions.find(item=>item.id===recordId):preset,type=record?.type||'House Reminder',week=currentWeek(),form=document.getElementById('weeklyForm');form.reset();document.getElementById('weeklyTitle').textContent=recordId?'Edit weekly item':'Add weekly item';document.getElementById('weeklyEyebrow').textContent=weekTitle().toUpperCase();document.getElementById('weeklyResponsible').innerHTML=weeklyAdminOptions(record?.responsibleId||'');form.elements.type.value=type;form.elements.title.value=record?.title||'';form.elements.dueDate.value=record?.dueDate||localDateIso();form.elements.dueTime.value=record?.dueTime||'';form.elements.message.value=record?.message||'';form.elements.notes.value=record?.notes||'';form.elements.linkedModule.value=record?.linkedModule||defaultWeeklyModule(type);form.elements.recurring.checked=Boolean(record?.recurring);fillWeeklyStatus(type,record?.status);setWeeklyFormVisibility(type);document.getElementById('weeklyDialog').showModal()}
function saveWeeklyForm(event){event.preventDefault();let form=event.currentTarget,data=Object.fromEntries(new FormData(form));data.recurring=form.elements.recurring.checked;data.weekStart=weekForDate(data.dueDate);data.updatedAt=new Date().toISOString();if(weeklyEditId){let index=state.weeklyActions.findIndex(item=>item.id===weeklyEditId);state.weeklyActions[index]={...state.weeklyActions[index],...data}}else state.weeklyActions.push({id:id('w'),createdAt:new Date().toISOString(),...data});document.getElementById('weeklyDialog').close();save('Weekly item saved')}
function updateWeeklyStatus(itemId,status){let item=state.weeklyActions.find(row=>row.id===itemId);if(!item)return;item.status=status;item.completedAt=weeklyDone(item)?new Date().toISOString():'';save('Status updated')}
async function copyWeeklyMessage(itemId){let item=state.weeklyActions.find(row=>row.id===itemId);if(!item?.message)return;try{await navigator.clipboard.writeText(item.message);toast('Message copied')}catch{toast('Could not copy the message on this device')}}
function carryWeeklyItem(itemId,quiet=false){let item=state.weeklyActions.find(row=>row.id===itemId);if(!item)return false;let due=new Date(`${item.dueDate}T12:00:00`);due.setDate(due.getDate()+7);let nextDate=localDateIso(due),exists=state.weeklyActions.some(row=>row.carriedFrom===item.id&&row.dueDate===nextDate);if(exists)return false;state.weeklyActions.push({...item,id:id('w'),weekStart:weekForDate(nextDate),dueDate:nextDate,status:weeklyStatusOptions(item.type)[0],recurring:false,carriedFrom:item.id,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()});if(!quiet)save('Item carried into next week');return true}
function carryForwardWeek(){let unfinished=weeklyItems().filter(item=>!weeklyDone(item)),count=unfinished.reduce((total,item)=>total+(carryWeeklyItem(item.id,true)?1:0),0);if(count)save(`${count} unfinished item${count===1?'':'s'} carried forward`);else toast('There are no new unfinished items to carry forward')}
function createWeeklyFollowup(itemId){let item=state.weeklyActions.find(row=>row.id===itemId);if(!item)return;let due=new Date();due.setDate(due.getDate()+1);openWeeklyForm(null,{type:'Reach-out',title:`Follow up: ${item.title}`,dueDate:localDateIso(due),dueTime:item.dueTime,responsibleId:item.responsibleId,status:'Pending',message:item.type==='Reach-out'?(item.message||item.notes):`Follow up on ${item.title}`,linkedModule:item.linkedModule||'members',notes:'',actionPoints:''})}
function deleteWeeklyItem(itemId){if(!confirm('Delete this weekly item?'))return;state.weeklyActions=state.weeklyActions.filter(item=>item.id!==itemId);save('Weekly item deleted')}
function openCloseWeekSummary(){let stats=weeklyStats(),unfinished=stats.items.filter(item=>!weeklyDone(item)),dialog=document.getElementById('detailDialog');document.getElementById('detailEyebrow').textContent='CLOSE WEEK';document.getElementById('detailTitle').textContent=weekTitle();document.getElementById('detailBody').innerHTML=`<div class="close-week-summary"><div><strong>${stats.total}</strong><span>Actions</span></div><div><strong>${stats.done}</strong><span>Done</span></div><div><strong>${unfinished.length}</strong><span>Unfinished</span></div><div><strong>${stats.overdue}</strong><span>Overdue</span></div></div><p class="close-week-note">Closing the week saves this summary. Unfinished items remain available and can be carried forward separately.</p><div class="modal-actions inside"><button class="button primary" id="confirmCloseWeek">Close this week</button></div>`;dialog.showModal();document.getElementById('confirmCloseWeek').onclick=()=>{let existing=state.weeklyClosures.find(item=>item.weekStart===currentWeek().key),summary={total:stats.total,done:stats.done,unfinished:unfinished.length,overdue:stats.overdue};if(existing)Object.assign(existing,{summary,closedAt:new Date().toISOString()});else state.weeklyClosures.push({id:id('c'),weekStart:currentWeek().key,summary,closedAt:new Date().toISOString()});dialog.close();save('Week closed and summary saved')}}
const postRenderBeforeWeeklyWorkflow=postRenderEnhancements;
postRenderEnhancements=function(){postRenderBeforeWeeklyWorkflow();document.querySelectorAll('[data-weekly-status]').forEach(select=>select.onchange=()=>updateWeeklyStatus(select.dataset.weeklyStatus,select.value));document.querySelectorAll('[data-copy-weekly]').forEach(button=>button.onclick=()=>copyWeeklyMessage(button.dataset.copyWeekly));document.querySelectorAll('[data-weekly-module]').forEach(button=>button.onclick=()=>{current=button.dataset.weeklyModule;render()});document.querySelectorAll('[data-weekly-followup]').forEach(button=>button.onclick=()=>createWeeklyFollowup(button.dataset.weeklyFollowup));document.querySelectorAll('[data-weekly-carry]').forEach(button=>button.onclick=()=>carryWeeklyItem(button.dataset.weeklyCarry));document.querySelectorAll('[data-weekly-edit]').forEach(button=>button.onclick=()=>openWeeklyForm(button.dataset.weeklyEdit));document.querySelectorAll('[data-weekly-delete]').forEach(button=>button.onclick=()=>deleteWeeklyItem(button.dataset.weeklyDelete));let add=document.getElementById('addWeeklyItem'),carry=document.getElementById('carryWeek'),close=document.getElementById('closeWeek'),handler=document.getElementById('weeklyHandler');if(add)add.onclick=()=>openWeeklyForm();if(carry)carry.onclick=carryForwardWeek;if(close)close.onclick=openCloseWeekSummary;if(handler)handler.onchange=()=>updateWeeklyHandler(handler.value)};
document.getElementById('weeklyType').onchange=event=>{fillWeeklyStatus(event.target.value);setWeeklyFormVisibility(event.target.value)};
document.getElementById('weeklyForm').onsubmit=saveWeeklyForm;
document.getElementById('weeklyClose').onclick=()=>document.getElementById('weeklyDialog').close();
document.getElementById('weeklyCancel').onclick=()=>document.getElementById('weeklyDialog').close();

/* Unified operations: Activities are events; Weekly Actions are admin work. */
let calendarRecordFilter='All';
function normalizeOperationalData(){let changed=false,activityStatus={Planned:'Upcoming','In Progress':'Upcoming',Completed:'Held'},activityType={Outreach:'Other',Evangelism:'Other',Hangout:'Other'},actionType={Meeting:'General Task',Schedule:'Schedule Preparation'},doneStatuses=['Sent','Completed','Cancelled','Reached'];state.activities.forEach(activity=>{let status=activityStatus[activity.status]||activity.status||'Upcoming',type=activityType[activity.type]||activity.type||'Other';if(status!==activity.status||type!==activity.type){activity.status=status;activity.type=type;changed=true}});state.weeklyActions.forEach(action=>{let type=actionType[action.type]||action.type||'General Task',status=action.status==='In Progress'||action.status==='Drafting'?'In Progress':doneStatuses.includes(action.status)?'Done':['To Do','Done'].includes(action.status)?action.status:'To Do';if(type!==action.type||status!==action.status){action.type=type;action.status=status;changed=true}});if(Array.isArray(state.tasks)&&state.tasks.length){state.tasks.forEach(task=>{if(state.weeklyActions.some(action=>action.migratedTaskId===task.id))return;state.weeklyActions.push({id:id('w'),type:'General Task',title:task.title||'Task',dueDate:(task.deadline||'').slice(0,10),dueTime:(task.deadline||'').includes('T')?task.deadline.slice(11,16):'',responsibleId:task.assigneeId||'',status:task.status==='Completed'?'Done':task.status==='Awaiting Review'?'In Progress':'To Do',notes:task.notes||'',relatedActivityId:task.activityId||'',linkedModule:'',recurring:false,migratedTaskId:task.id,createdAt:new Date().toISOString()});changed=true});state.tasks=[];changed=true}if(changed){localStorage.setItem(STORAGE_KEY,JSON.stringify(state));queueCloudSync()}}
function operationalWeekItems(){normalizeOperationalData();let {start,end}=currentWeek(),from=localDateIso(start),to=localDateIso(end),activities=state.activities.filter(activity=>activity.date>=from&&activity.date<=to).map(record=>({kind:'activity',date:record.date,time:record.time||'',record})),actions=state.weeklyActions.filter(action=>action.dueDate>=from&&action.dueDate<=to).map(record=>({kind:'action',date:record.dueDate,time:record.dueTime||'',record}));return [...activities,...actions].sort((a,b)=>`${a.date}T${a.time}`.localeCompare(`${b.date}T${b.time}`)||a.kind.localeCompare(b.kind))}
function actionDone(action){return action.status==='Done'}
function activityDone(activity){return ['Held','Cancelled'].includes(activity.status)}
function operationalOverdue(item){let done=item.kind==='activity'?activityDone(item.record):actionDone(item.record);if(done||!item.date)return false;return new Date(`${item.date}T${item.time||'23:59'}:00`)<new Date()}
function operationalStats(){let items=operationalWeekItems(),done=items.filter(item=>item.kind==='activity'?activityDone(item.record):actionDone(item.record)).length,overdue=items.filter(operationalOverdue).length,upcoming=items.length-done-overdue;return {items,total:items.length,done,overdue,upcoming}}
function activityOperationalCard(activity){let related=state.weeklyActions.filter(action=>action.relatedActivityId===activity.id&&action.dueDate>=currentWeek().key&&action.dueDate<=localDateIso(currentWeek().end)),overdue=operationalOverdue({kind:'activity',date:activity.date,time:activity.time,record:activity});return `<article class="weekly-item scheduled-activity ${activityDone(activity)?'is-done':''} ${overdue?'is-overdue':''}"><div class="weekly-type-icon">◷</div><div class="weekly-item-main"><div class="weekly-item-title"><span class="weekly-type">Scheduled activity</span><h4>${esc(activity.title)}</h4></div><p>${esc(activity.type)} · ${esc(activity.venue||'Venue not set')} · Supervisor: ${esc(activity.coordinator||'Not assigned')}</p><div class="weekly-meta"><span>${dateFmt(activity.date,{weekday:'short',day:'numeric',month:'short'})}${activity.time?` · ${esc(activity.time)}`:''}</span>${related.length?`<span>${related.length} related action${related.length===1?'':'s'}</span>`:''}${overdue?'<strong>Overdue</strong>':''}</div>${related.length?`<div class="related-actions">${related.map(action=>`<span>${actionDone(action)?'✓':'○'} ${esc(action.title)}</span>`).join('')}</div>`:''}</div><div class="weekly-item-actions"><select data-activity-status="${activity.id}" aria-label="Status for ${esc(activity.title)}">${['Upcoming','Held','Cancelled','Rescheduled'].map(status=>`<option ${status===activity.status?'selected':''}>${status}</option>`).join('')}</select><div><button class="action" data-edit="activity" data-id="${activity.id}">Edit activity</button><button class="action" data-related-action="${activity.id}">Add related action</button><button class="action" data-open-attendance="${activity.id}">Attendance</button></div></div></article>`}
function actionResponsibleName(action){return WEEKLY_ADMINS.includes(action.responsibleId)?action.responsibleId:(memberName(action.responsibleId)==='Unknown'?'Unassigned':memberName(action.responsibleId))}
function weeklyActionCard(action){let related=state.activities.find(activity=>activity.id===action.relatedActivityId),overdue=operationalOverdue({kind:'action',date:action.dueDate,time:action.dueTime,record:action});return `<article class="weekly-item weekly-action ${actionDone(action)?'is-done':''} ${overdue?'is-overdue':''}"><div class="weekly-type-icon">${weeklyTypeIcon(action.type)}</div><div class="weekly-item-main"><div class="weekly-item-title"><span class="weekly-type">Weekly action · ${esc(action.type)}</span><h4>${esc(action.title)}</h4>${action.recurring?'<span class="recurring-tag">Weekly</span>':''}</div><p>${esc(action.message||action.reason||action.notes||'No additional note')}</p><div class="weekly-meta"><span>${esc(actionResponsibleName(action))}</span><span>${dateFmt(action.dueDate,{weekday:'short',day:'numeric',month:'short'})}${action.dueTime?` · ${esc(action.dueTime)}`:''}</span>${related?`<span>Related: ${esc(related.title)}</span>`:''}${action.outcome?`<span>Outcome: ${esc(action.outcome)}</span>`:''}${overdue?'<strong>Overdue</strong>':''}</div></div><div class="weekly-item-actions"><select data-weekly-status="${action.id}" aria-label="Status for ${esc(action.title)}">${['To Do','In Progress','Done'].map(status=>`<option ${status===action.status?'selected':''}>${status}</option>`).join('')}</select><div>${action.type==='House Reminder'&&action.message?`<button class="action" data-copy-weekly="${action.id}">Copy message</button>`:''}<button class="action" data-weekly-edit="${action.id}">Edit</button><button class="action danger" data-weekly-delete="${action.id}">Delete</button></div></div></article>`}
function operationalDayGroups(items){let groups=items.reduce((result,item)=>((result[item.date]??=[]).push(item),result),{});return Object.entries(groups).map(([date,records])=>`<section class="operation-day"><div class="operation-day-head"><h3>${dateFmt(date,{weekday:'long',day:'numeric',month:'long'})}</h3><span>${records.length}</span></div><div class="weekly-list">${records.map(item=>item.kind==='activity'?activityOperationalCard(item.record):weeklyActionCard(item.record)).join('')}</div></section>`).join('')}
views.week=()=>{let stats=operationalStats(),handler=weeklyHandlerName();return `<section class="weekly-hero"><div><p class="eyebrow">OPERATIONAL COMMAND CENTRE</p><h2>${weekTitle()}</h2><label class="week-handler"><span>Week handled by</span><select id="weeklyHandler" aria-label="Admin handling this week">${WEEKLY_ADMINS.map(admin=>`<option ${admin===handler?'selected':''}>${admin}</option>`).join('')}</select></label><p>Activities happening this week and the actions required to support them.</p></div><div class="weekly-hero-actions"><button class="button gold" id="addWeeklyItem">＋ Weekly Action</button></div></section><div class="weekly-summary"><div><span>Total</span><strong>${stats.total}</strong></div><div><span>Done</span><strong>${stats.done}</strong></div><div><span>Upcoming</span><strong>${stats.upcoming}</strong></div><div class="${stats.overdue?'alert':''}"><span>Overdue</span><strong>${stats.overdue}</strong></div></div><div class="operation-days">${operationalDayGroups(stats.items)||'<div class="weekly-empty"><strong>Nothing scheduled for this week.</strong><span>Add an Activity or Weekly Action and it will appear here automatically when dated within this Sunday–Saturday period.</span></div>'}</div>`}
function weeklyItems(){normalizeOperationalData();return state.weeklyActions.filter(action=>action.dueDate>=currentWeek().key&&action.dueDate<=localDateIso(currentWeek().end)).sort((a,b)=>`${a.dueDate||''}T${a.dueTime||''}`.localeCompare(`${b.dueDate||''}T${b.dueTime||''}`))}
function weeklyDone(item){return actionDone(item)}
function weeklyStatusOptions(){return ['To Do','In Progress','Done']}
function weeklyTypeIcon(type){return {'House Reminder':'▣','Reach-out':'☎','Update':'↻','Schedule Preparation':'◷','General Task':'✓'}[type]||'•'}
function defaultWeeklyModule(type){return {'Schedule Preparation':'schedule',Update:'members','Reach-out':'members'}[type]||''}
function weeklyAdminOptions(selected=''){return `<option value="">Unassigned</option>${WEEKLY_ADMINS.map(admin=>`<option value="${admin}" ${admin===selected?'selected':''}>${admin}</option>`).join('')}`}
function setWeeklyFormVisibility(type){let message=document.querySelector('.weekly-message-field'),person=document.querySelector('.weekly-person-field'),reason=document.querySelector('.weekly-reason-field'),outcome=document.querySelector('.weekly-outcome-field'),linked=document.querySelector('.weekly-linked-field');message.hidden=type!=='House Reminder';person.hidden=type!=='Reach-out';reason.hidden=type!=='Reach-out';outcome.hidden=type!=='Reach-out';linked.hidden=!['Schedule Preparation','Update'].includes(type);if(type==='Schedule Preparation')document.querySelector('[name="linkedModule"]').value='schedule'}
function openWeeklyForm(recordId=null,preset={}){normalizeOperationalData();weeklyEditId=recordId;let record=recordId?state.weeklyActions.find(item=>item.id===recordId):preset,type=record?.type||'General Task',form=document.getElementById('weeklyForm');form.reset();document.getElementById('weeklyTitle').textContent=recordId?'Edit weekly action':'Add weekly action';document.getElementById('weeklyEyebrow').textContent='ADMINISTRATIVE WORK';document.getElementById('weeklyResponsible').innerHTML=weeklyAdminOptions(record?.responsibleId||'');document.getElementById('weeklyRelatedActivity').innerHTML=`<option value="">None</option>${state.activities.slice().sort((a,b)=>(a.date||'').localeCompare(b.date||'')).map(activity=>`<option value="${activity.id}" ${activity.id===record?.relatedActivityId?'selected':''}>${esc(activity.title)} · ${dateFmt(activity.date,{day:'numeric',month:'short'})}</option>`).join('')}`;form.elements.type.value=type;form.elements.title.value=record?.title||'';form.elements.dueDate.value=record?.dueDate||localDateIso();form.elements.dueTime.value=record?.dueTime||'';form.elements.status.value=record?.status||'To Do';form.elements.relatedActivityId.value=record?.relatedActivityId||'';form.elements.linkedModule.value=record?.linkedModule||defaultWeeklyModule(type);form.elements.person.value=record?.person||'';form.elements.message.value=record?.message||'';form.elements.reason.value=record?.reason||'';form.elements.outcome.value=record?.outcome||'';form.elements.notes.value=record?.notes||'';form.elements.recurring.checked=Boolean(record?.recurring);fillWeeklyStatus(type,record?.status||'To Do');setWeeklyFormVisibility(type);document.getElementById('weeklyDialog').showModal()}
function updateActivityStatus(activityId,status){let activity=state.activities.find(item=>item.id===activityId);if(!activity)return;activity.status=status;save('Activity status updated')}
function calendarActionGroup(action){return {'House Reminder':'Reminders','Reach-out':'Reach-outs','Schedule Preparation':'Schedules',Update:'Updates'}[action.type]||'Actions'}
function calendarRecordMatches(item){if(calendarRecordFilter==='All')return true;if(calendarRecordFilter==='Activities')return item.kind==='activity';return item.kind==='action'&&calendarActionGroup(item.record)===calendarRecordFilter}
function legacyUnifiedActivityCalendarView(){normalizeOperationalData();return ''}
function activityCalendarView(){
  normalizeOperationalData();
  let filters=['All','Activities','Reminders','Reach-outs','Schedules','Updates'],year=calendarDate.getFullYear(),month=calendarDate.getMonth(),first=new Date(year,month,1),last=new Date(year,month+1,0),firstOffset=first.getDay(),lastOffset=last.getDay(),start=new Date(year,month,1-firstOffset),end=new Date(year,month,last.getDate()+(6-lastOffset)),weeks=[];
  for(let cursor=new Date(start);cursor<=end;cursor.setDate(cursor.getDate()+7)){
    let weekStart=new Date(cursor),key=localDateIso(weekStart),days=[];
    for(let offset=0;offset<7;offset++){
      let date=new Date(weekStart);date.setDate(date.getDate()+offset);let iso=localDateIso(date),items=[...state.activities.filter(activity=>activity.date===iso).map(record=>({kind:'activity',record,time:record.time||''})),...state.weeklyActions.filter(action=>action.dueDate===iso).map(record=>({kind:'action',record,time:record.dueTime||''}))].filter(calendarRecordMatches).sort((a,b)=>a.time.localeCompare(b.time)),muted=date.getMonth()!==month;
      days.push(`<div class="calendar-day ${muted?'muted':''}"><button class="calendar-date-add" data-calendar-date="${iso}" aria-label="Add activity on ${dateFmt(iso)}"><b>${date.getDate()}</b><i>＋ Activity</i></button><div class="calendar-events">${items.map(item=>item.kind==='activity'?`<button class="calendar-event calendar-activity" data-edit="activity" data-id="${item.record.id}"><strong>${esc(item.time)}</strong> ${esc(item.record.title)}<small>${esc(item.record.type)} · ${esc(item.record.status)}</small></button>`:`<button class="calendar-event calendar-action" data-weekly-edit="${item.record.id}"><strong>${esc(item.time)}</strong> ${esc(item.record.title)}<small>${esc(calendarActionGroup(item.record))} · ${esc(item.record.status)}</small></button>`).join('')}</div></div>`)
    }
    let handler=handlerForWeek(key);
    weeks.push(`<section class="calendar-week"><div class="week-supervisor"><div><strong>Week of ${dateFmt(key,{day:'numeric',month:'short'})}</strong><small>Week handled by</small></div><select data-week-supervisor="${key}" aria-label="Admin handling week of ${dateFmt(key)}">${WEEKLY_ADMINS.map(admin=>`<option value="${admin}" ${admin===handler?'selected':''}>${admin}</option>`).join('')}</select></div><div class="calendar-grid">${days.join('')}</div></section>`)
  }
  return `<div class="calendar-toolbar"><select class="filter" id="calendarRecordFilter">${filters.map(filter=>`<option ${filter===calendarRecordFilter?'selected':''}>${filter}</option>`).join('')}</select><span class="spacer"></span><button class="button ghost" data-calendar-nav="-1">‹</button><h2>${first.toLocaleDateString('en-NG',{month:'long',year:'numeric'})}</h2><button class="button ghost" data-calendar-nav="1">›</button><button class="button primary" data-add="activity">＋ Add activity</button></div><div class="calendar calendar-with-supervisors"><div class="calendar-weekdays">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(day=>`<span>${day}</span>`).join('')}</div>${weeks.join('')}</div>`
}
views.activities=()=>activityCalendarView();
function weeklyDashboardCard(){let stats=operationalStats(),urgent=stats.items.filter(item=>operationalOverdue(item)||item.date===localDateIso()).slice(0,3);return `<section class="card this-week-card"><div class="card-head"><div><h3>${weekTitle()}</h3><p>Week admin: ${esc(weeklyHandlerName())}</p></div><button class="button small primary right" data-page-jump="week">Open This Week</button></div><div class="this-week-body"><div class="this-week-counts"><div><strong>${stats.total}</strong><span>Total</span></div><div><strong>${stats.done}</strong><span>Done</span></div><div><strong>${stats.upcoming}</strong><span>Upcoming</span></div><div class="${stats.overdue?'alert':''}"><strong>${stats.overdue}</strong><span>Overdue</span></div></div><div class="this-week-urgent">${urgent.map(item=>`<button data-page-jump="week"><span class="weekly-type">${item.kind==='activity'?'Activity':'Action'}</span><strong>${esc(item.record.title)}</strong><small>${operationalOverdue(item)?'Overdue':`Due ${esc(item.time||'today')}`}</small></button>`).join('')||'<p>No urgent items today.</p>'}</div></div></section>`}
const unifiedPostRender=postRenderEnhancements;
postRenderEnhancements=function(){unifiedPostRender();document.querySelectorAll('[data-activity-status]').forEach(select=>select.onchange=()=>updateActivityStatus(select.dataset.activityStatus,select.value));document.querySelectorAll('[data-related-action]').forEach(button=>button.onclick=()=>openWeeklyForm(null,{type:'General Task',title:'',dueDate:state.activities.find(activity=>activity.id===button.dataset.relatedAction)?.date||localDateIso(),relatedActivityId:button.dataset.relatedAction,status:'To Do'}));let filter=document.getElementById('calendarRecordFilter');if(filter)filter.onchange=()=>{calendarRecordFilter=filter.value;render()};let related=document.getElementById('weeklyRelatedActivity');if(related)related.onchange=()=>{let activity=state.activities.find(item=>item.id===related.value);if(activity&&!document.getElementById('weeklyForm').elements.dueDate.value)document.getElementById('weeklyForm').elements.dueDate.value=activity.date}};
document.getElementById('weeklyType').onchange=event=>{fillWeeklyStatus(event.target.value,'To Do');setWeeklyFormVisibility(event.target.value)};
document.getElementById('weeklyForm').onsubmit=saveWeeklyForm;

let initialPage=location.hash.slice(1);if(pages.some(page=>page[0]===initialPage))current=initialPage;
render();initCloud();
